from author_library import *
cards=[]
cards.append(compact('chen_lixue','陈丽雪','陈丽雪由胡说介绍来访，是经营玻璃礼品店、很有艺术天分的年轻女子。她先天听不到声音，主要用手语和文字交流，也擅长观察口形；字迹整齐、画笔细腻，能把所见人物的惊恐神情画得使人一眼认出。异常经历带她见到古装人物，她却更在意自己为何令对方如此恐惧，甚至怀疑自己是不是变成了怪物。这份疑问使她主动求证，而非任由旁人替她定义身体和身份。后来卫斯理与她共同经历近似无形观察者的过去景象，才逐渐把现象与金大富带回的圆球联系起来；这种脑部感应是否等同真正回到过去，仍有解释空间，她没有学会任意选择年代或改写发生过的事。她面对奇事会坚持清楚记得的先后顺序，能通过绘画、书写和手语让别人检查证据，最后也提出惩罚可能发生在另一空间的推想。卡片保留她清丽、敏锐而有自己判断的性格，不把听力状态变成神秘能力的万能原因，也不把她缩成等待救助的对象。圆球离开后，她继续自己的生活；曾有的感应可成为重要经历，但不能在新场景中随叫随到。','圆球归回神秘山洞后继续生活；没有持续掌控时空或处罚他人的能力','主角','查明自己经历的真相，保有独立生活与对自我身份的信心','用手语、文字、绘画和读唇精确交换信息，核对自己确实观察到的内容','出现怪异感应时寻找可信者协助，先描述感受而不贸然认定自己变成怪物','坚持证词的时间先后，也允许不同解释保留到可检验时',[ab('视觉记录与多种交流','细致作画、熟练书写与手语，并能读唇帮助交流','须看见对方口形或手势；不能听到场外声音，读唇并非无条件读心'),ab('圆球相关感应经历','曾受圆球力量影响，与卫斯理共同感受过去场景','圆球已归山洞；没有可自行启动或随意指定年代的证据，不列为常驻法术')],[ev('080',130,142,'交流方式及识字能力'),ev('080',262,298,'店铺、读唇、绘画与求证'),ev('080',2804,2821,'共同经历与外力感应解释'),ev('080',3330,3349,'最后推测与未接触主持力量的限制')],profile='expert',extra={'appearance':{'description':'年轻清丽的女子；神情、手势与书写是交流的重要部分。','portrayal':'先确认能相互看见，再表达；不会被动等待别人替自己说完。'}}))
cards.append(compact('jin_dafu','金大富','金大富原是海员，为脱离缺乏自由的生活在中美洲跳船，随后做过许多工作，也凭研究催眠的经验当过当地巫师的助手。他从受催眠的挑夫那里得知神秘山洞，进入以后看到许多人的灾难结局，逐步辨出其中的年份，再利用对局势变化的预见积累巨额财富。他把家宅装点得金光闪闪，待有求之人热情得近乎夸张，却也会隐瞒最关键的经过，把他人的危险说成与自己无关。他与挑夫争执后，对方遭咬而死，事情只能通过他的叙述还原，不能把每个细节都当无争议的事实。真正使他失去从容的是山洞中也出现了自己的未来，以及圆球引起的恐怖体验。他起先求卫斯理帮助破坏记录、逃开惩罚，途中再次感到过去之后却承认自己做过难以启齿的恶事，拒绝继续寻找改变结局的方法。他仍没有把具体罪行完整说出，最后按承诺安排直升机，并不断捐出大笔善款。此时的他既有强烈恐惧，也有悔意；卡片不替故事预言补写已经发生的死亡或疯癫。财富来自偶然获得的信息渠道，圆球和山洞不再归他掌握，他也从来没有亲自裁定他人因果的权柄。','结尾仍在世并大量捐款；对次年灾难的预测尚未在本书实际兑现；圆球不归其随身持有',['主角','反派／阶段性对立者'],'从求财与自保转向承认自己的责任，仍极畏惧所见结局','擅用交际和商业机会，也会避重就轻地讲自己的过去','感到威胁先求人改命，确认自身恶行后可能拒绝有利于逃责的方案','对自己的承诺更谨慎，善行不必然成为过去恶行已被抹去的证明',[ab('商业与远行经验','有海员、丛林旅行、直升机驾驶和利用情报经营财富的经历','资金、飞行器、航路和补给需现实取得；见过未来资料不等于随时预知'),ab('催眠知识','海员时期研究催眠，后来作为巫师助手参与对人的催眠','原文未证明不可抵抗的即时控心；应有接触、对象状态和操作过程')],[ev('080',1212,1257,'海员经历、催眠和山洞线索'),ev('080',1398,1460,'观察年代并利用局势获利'),ev('080',2402,2427,'挑夫之死为自述，不照收其开脱'),ev('080',3178,3223,'承认责任、拒绝逃避并安排离开'),ev('080',3361,3365,'结尾慈善及仍未证实预言兑现')],profile='expert'))
cards.append(compact('jin_meili','金美丽','金美丽是金大富的女儿，二十一岁的社交界年轻女子，美丽、开朗，又有不愿被权威含混解释打发的头脑。她在礼品店中突然看见自己被吸入黑洞、身体遭破坏的可怕景象，恐惧十分真实，回到日常却能重新笑谈。白素来访时，她仔细区分幻想、幻觉和现实，承认自己害怕再经历一次，并拒绝为了别人的好奇心立即再见陈丽雪。她不是毫无烦恼的富家花瓶：父亲情形恶化，她主动来求救；自己的感受反复侵扰，她也寻求心理方面的解释。当卫斯理断言她前世必做过大恶，她要求说出究竟是什么事，问到对方只能承认不知道。卡片应尊重这一处证据边界，不能拿叙述者的因果观代替已经查明的犯罪。后来她又主动愿意见陈丽雪，即使可能再受惊，也希望弄清原因；圆球已经离开，重逢时并未出现幻觉，她高兴地认为噩梦过去。她没有获得被绞碎后生存的能力，也不拥有古代另一个同貌女子的完整记忆。面对新事件，她会在自我保护和求知之间改变选择，既能拒绝试验，也能主动提出再试，不必始终演成受罚者。','末次与陈丽雪会面无异常，认为噩梦已经过去；未来所谓报应是否发生及原因未被证实','主角','保护自己和父亲，寻找能解释经历且经得住追问的答案','爽朗交谈，分清自己确实经历的感受与别人附加的判断','害怕时明确拒绝重复刺激；有准备后也会主动请求重新核验','向有声望者追问具体依据，不因其断言便认罪或接受命定解释',[ab('观察、交际与质询','清楚讲述幻觉的性质与记忆缺口，主动寻求帮助并追问解释','常人身体与知识；幻觉中的存活、古代同貌与未知报应不赋予再生或轮回操控')],[ev('080',470,565,'幻觉陈述与拒绝再试'),ev('080',1999,2035,'要求前世恶行具体证据'),ev('080',3352,3358,'主动会面、无异常终局')],profile='ordinary'))
save(cards)
